import bpy, math
from mathutils import Vector
def move(name, loc, rot=None):
    o = bpy.data.objects.get(name)
    if o:
        o.location = loc
        if rot is not None: o.rotation_euler = rot
    return o

# --- raise roof structure to clear hat (hat top ~3.28) ---
for n in ["BeamFront","BeamBack"]:
    o=bpy.data.objects.get(n)
    if o: o.location[2]=3.25
for n in ["BeamL","BeamR"]:
    o=bpy.data.objects.get(n)
    if o:
        o.location[2]=3.25
        o.dimensions=(0.16,2.9,0.16)
roof=bpy.data.objects.get("Roof")
if roof: roof.location=(0,-0.32,3.55)
# posts taller
import re
for o in bpy.data.objects:
    if o.name.startswith("Post_"):
        o.location[2]=1.65
        o.dimensions=(0.16,0.16,3.3) if False else o.dimensions
        # cylinder depth axis is Z; scale z
        o.scale[2]=3.3/2.9
# awning up
for i in range(9):
    o=bpy.data.objects.get(f"Awning{i}")
    if o: o.location[2]=3.02; o.location[1]=1.55
# sign higher
move("SignBoard",(0,1.72,3.32),(math.radians(15),0,0))
move("SignPaper",(0,1.76,3.32),(math.radians(15),0,0))
st=bpy.data.objects.get("SignText")
if st: st.location=(-0.85,1.81,3.20)
# noren: hang from front beam down, bottom at ~2.55 (above eyes 2.12, below hat brim 2.58? brim 2.58 -> noren bottom 2.6 just above brim)
for i,x in enumerate([-1.05,0.0,1.05]):
    n=bpy.data.objects.get(f"Noren{i}")
    if n:
        n.location=(x,0.95,2.92)
        n.dimensions=(1.0,0.02,0.65) if False else n.dimensions
        # plane dims: (x,y,0) but rotated; set scale instead: keep
    s=bpy.data.objects.get(f"NorenStripe{i}")
    if s: s.location=(x,0.955,2.63)
# lanterns up under awning
for i,x in enumerate([-1.5,0.0,1.5]):
    for suffix,dz in [("",2.62),("Top",2.89),("Bot",2.35)]:
        # names: Lantern{i}, LantTop{i}, LantBot{i}
        nm = f"Lantern{i}" if suffix=="" else (f"LantTop{i}" if suffix=="Top" else f"LantBot{i}")
        o=bpy.data.objects.get(nm)
        if o: o.location=(x,1.55,dz)
    c=bpy.data.objects.get(f"Cord{i}")
    if c:
        c.location=(x,1.55,3.05); c.dimensions=(0.024,0.024,0.35)
# side noren up too
for x in (-2.05,2.05):
    o=bpy.data.objects.get(f"SideNoren{x}")
    if o: o.location=(x,-0.3,2.9)

# camera: pull back a bit, aim at chef face
cam=bpy.data.objects.get("Camera")
cam.location=(4.3,5.6,3.1)
target=Vector((0,-0.3,1.7))
cam.rotation_euler=(target-cam.location).to_track_quat('-Z','Y').to_euler()
print("raise done")
